def window_indices(length, t, history, horizon):
    if min(length, history, horizon) <= 0 or not 0 <= t < length:
        raise ValueError('invalid window configuration')
    obs = [i if 0 <= i < length else None for i in range(t-history+1, t+1)]
    act = [i if 0 <= i < length else None for i in range(t, t+horizon)]
    return obs, act

def block_attention_mask(valid, block_start):
    if not valid or not valid[0]:
        raise ValueError("nonempty batch and sequence required")
    n = len(valid[0])
    if len(block_start) != n or any(len(row) != n for row in valid):
        raise ValueError("inconsistent lengths")
    if any(type(value) is not bool for row in valid for value in row):
        raise ValueError("valid entries must be bool")
    if any(type(value) is not bool for value in block_start):
        raise ValueError("block_start entries must be bool")
    groups, total = [], 0
    for start in block_start:
        total += int(start)
        groups.append(total)
    return [[[bool(row[i] and row[j] and groups[j] <= groups[i])
              for j in range(n)] for i in range(n)] for row in valid]

import math

def categorical_logit_gradient(probabilities,chosen,advantage):
    if not probabilities or not 0<=chosen<len(probabilities):
        raise ValueError('invalid action')
    if any(p<0 or not math.isfinite(p) for p in probabilities) or not math.isclose(sum(probabilities),1.0):
        raise ValueError('invalid distribution')
    return [advantage*(p-(1.0 if j==chosen else 0.0)) for j,p in enumerate(probabilities)]

