def group_advantage(rewards, eps=1e-6):
    if rewards.ndim!=2 or rewards.shape[1]<2: raise ValueError('expect [B,G], G>=2')
    mean=rewards.mean(-1,keepdim=True)
    std=rewards.std(-1,keepdim=True,unbiased=False)
    return (rewards-mean)/(std+eps)

